// Orquestador de estados conversacionales.
// Recupera estado previo, decide siguiente pregunta y acciones.
interface Elementos {
  ac_units: number;
  antennas: number;
  pipes: number;
  cables: number;
  gutters: number;
  solar_panels: number;
}
interface ConversacionState {
  step: number;
  questions: string[];
  answers: {
    perimeter_roof_m?: number;
    facade_area_m2?: number;
    heights?: number;
    elements?: Elementos;
    images?: { fachada: number; cubierta: number };
  };
  awaitingConfirmation?: boolean;
  resumenGenerado?: boolean;
  ultimaPregunta?: string;
  vision?: any;
  catastro?: any;
}
function defaultState(): ConversacionState {
  return {
    step: 0,
    questions: [
      'Indica el perímetro de la cubierta (m). Ej.: 145,6',
      'Indica la superficie total de fachada (m²).',
      '¿Cuál es el número de alturas del edificio?',
      '¿Cuántos elementos hay que desmontar y volver a montar (aires, antenas, canaletas, tuberías, cables, placas solares)? Detállalo por tipo.',
      'Sube fotos de las fachadas y de la cubierta.'
    ],
    answers: {
      elements: {
        ac_units: 0,
        antennas: 0,
        pipes: 0,
        cables: 0,
        gutters: 0,
        solar_panels: 0
      },
      images: { fachada: 0, cubierta: 0 }
    }
  };
}
const item = items[0];
const incoming = item.json.body || item.json;
const phone = incoming.from || incoming.sender || incoming.wa_id || 'desconocido';
const rawState = item.json.estadoSesion as string | undefined;
let state: ConversacionState = rawState ? JSON.parse(rawState) : defaultState();
const messageType = incoming.type || item.json.type || 'text';
const result = {
  action: 'ask',
  reply: '',
  state,
  phone,
  incoming,
  needsValidation: false,
  requiresPhotos: false,
  logLevel: 'info'
};
function avanzarPregunta() {
  state.step += 1;
  if (state.step < state.questions.length) {
    state.ultimaPregunta = state.questions[state.step];
    result.reply = state.questions[state.step];
  } else {
    state.ultimaPregunta = undefined;
    result.reply = 'Gracias, estoy recopilando la información y preparando el presupuesto.';
    result.action = 'calcular';
  }
}
if (state.awaitingConfirmation) {
  const texto = (incoming.text?.body || incoming.message || '').trim().toLowerCase();
  if (texto.includes('si')) {
    result.reply = 'Perfecto, estoy creando el presupuesto en Odoo.';
    result.action = 'crear_odoo';
  } else if (texto.includes('no')) {
    result.reply = 'Sin problema, puedes solicitar cambios o pedirnos que lo creemos más adelante.';
    result.action = 'fin';
  } else {
    result.reply = '¿Deseas que creemos el presupuesto en Odoo? Responde con "Sí" o "No".';
  }
  return [{ json: result }];
}
if (messageType === 'image') {
  state.answers.images = state.answers.images || { fachada: 0, cubierta: 0 };
  const caption = (incoming.image?.caption || '').toLowerCase();
  if (caption.includes('fachada')) {
    state.answers.images.fachada += 1;
  } else if (caption.includes('cubierta')) {
    state.answers.images.cubierta += 1;
  } else {
    if (state.answers.images.fachada < 2) {
      state.answers.images.fachada += 1;
    } else {
      state.answers.images.cubierta += 1;
    }
  }
  result.reply = 'Foto recibida, gracias. Continúa enviando el resto si aún faltan.';
  if (state.answers.images.fachada >= 2 && state.answers.images.cubierta >= 1 && state.step < 4) {
    state.step = 4;
    avanzarPregunta();
  } else {
    result.action = 'registrar_imagen';
  }
  result.state = state;
  return [{ json: result }];
}
if (messageType === 'document') {
  result.reply = 'He recibido tu archivo. Si es una foto, por favor envíala como imagen para poder procesarla.';
  result.action = 'solo_respuesta';
  result.state = state;
  return [{ json: result }];
}
const texto = (incoming.text?.body || incoming.message || '').trim();
if (!texto) {
  result.reply = 'No pude leer el mensaje, ¿podrías repetirlo?';
  result.state = state;
  return [{ json: result }];
}
switch (state.step) {
  case 0: {
    result.state = state;
    result.action = 'validar_perimetro';
    result.value = texto;
    result.question = state.questions[state.step];
    result.needsValidation = true;
    break;
  }
  case 1: {
    result.state = state;
    result.action = 'validar_fachada';
    result.value = texto;
    result.question = state.questions[state.step];
    result.needsValidation = true;
    break;
  }
  case 2: {
    result.state = state;
    result.action = 'validar_alturas';
    result.value = texto;
    result.question = state.questions[state.step];
    result.needsValidation = true;
    break;
  }
  case 3: {
    result.state = state;
    result.action = 'validar_elementos';
    result.value = texto;
    result.question = state.questions[state.step];
    result.needsValidation = true;
    break;
  }
  case 4: {
    result.reply = 'Necesito al menos 2 fotos de fachada (frontal/lateral) y 1 de cubierta.';
    result.action = 'solicitar_fotos';
    result.requiresPhotos = true;
    break;
  }
  default: {
    result.reply = 'Estoy repasando la información para generar el presupuesto.';
    result.action = 'calcular';
    break;
  }
}
return [{ json: result }];

// Valida entradas numéricas y consistencia.
const item = items[0];
const data = item.json;
const state = data.state;
const respuesta = { ...data };
if (!data.needsValidation) {
  return [{ json: respuesta }];
}
const valorTexto = String(data.value || '').replace(',', '.');
const numero = Number(valorTexto);
const error = (mensaje: string) => {
  respuesta.reply = mensaje;
  respuesta.action = 'reintentar';
  respuesta.logLevel = 'warn';
  return [{ json: respuesta }];
};
switch (data.action) {
  case 'validar_perimetro': {
    if (!isFinite(numero) || numero <= 0) {
      return error('El perímetro debe ser un número mayor que 0. Intenta de nuevo, por favor.');
    }
    state.answers.perimeter_roof_m = Number(numero.toFixed(2));
    break;
  }
  case 'validar_fachada': {
    if (!isFinite(numero) || numero <= 0) {
      return error('La superficie de fachada debe ser positiva.');
    }
    state.answers.facade_area_m2 = Number(numero.toFixed(2));
    if (state.answers.heights && state.answers.facade_area_m2 < (state.answers.perimeter_roof_m || 0) * state.answers.heights * 2) {
      respuesta.reply = 'Revisa si la superficie de fachada es correcta respecto al perímetro y las alturas. ¿Puedes confirmarla?';
      respuesta.action = 'confirmar_valor';
      return [{ json: respuesta }];
    }
    break;
  }
  case 'validar_alturas': {
    if (!Number.isInteger(numero) || numero <= 0) {
      return error('Las alturas deben ser un número entero mayor que 0.');
    }
    state.answers.heights = Number(numero);
    if (state.answers.facade_area_m2 && state.answers.facade_area_m2 < (state.answers.perimeter_roof_m || 0) * state.answers.heights * 2) {
      respuesta.reply = 'La superficie de fachada parece baja para las alturas indicadas. ¿Podrías revisarla?';
      respuesta.action = 'confirmar_valor';
      return [{ json: respuesta }];
    }
    break;
  }
  case 'validar_elementos': {
    const elementos: any = { ...state.answers.elements };
    const partes = valorTexto.split(/[,;]+/).map(p => p.trim());
    for (const parte of partes) {
      const match = parte.match(/(aires?|ac|clima|antenas?|canaletas?|tuber(?:ías|ias)|cables?|placas?|solares?|gutters?)[^0-9]*([0-9]+)/i);
      if (match) {
        const tipo = match[1].toLowerCase();
        const cantidad = Number(match[2]);
        if (tipo.includes('aire') || tipo.includes('ac') || tipo.includes('clima')) elementos.ac_units = (elementos.ac_units || 0) + cantidad;
        else if (tipo.includes('antena')) elementos.antennas = (elementos.antennas || 0) + cantidad;
        else if (tipo.includes('canalet')) elementos.gutters = (elementos.gutters || 0) + cantidad;
        else if (tipo.includes('tuber')) elementos.pipes = (elementos.pipes || 0) + cantidad;
        else if (tipo.includes('cable')) elementos.cables = (elementos.cables || 0) + cantidad;
        else if (tipo.includes('placa') || tipo.includes('solar')) elementos.solar_panels = (elementos.solar_panels || 0) + cantidad;
      }
    }
    state.answers.elements = elementos;
    break;
  }
  default:
    break;
}
respuesta.state = state;
respuesta.needsValidation = false;
return [{ json: respuesta }];

// Combina datos de usuario, visión y catastro para cálculos.
interface VisionEstimacion {
  facade_area_est?: number;
  openings_area_est?: number;
  ac_units?: number;
  pipes?: number;
  cables?: number;
  gutters?: number;
  solar_panels?: number;
  annotations?: any;
}
interface Elementos {
  ac_units: number;
  antennas: number;
  pipes: number;
  cables: number;
  gutters: number;
  solar_panels: number;
}
interface CapituloLinea {
  codigo: string;
  concepto: string;
  unidad: string;
  cantidad: number;
  largo?: number;
  ancho?: number;
  alto?: number;
  precio: number;
  importe: number;
  notas?: string;
}
interface Capitulo {
  code: string;
  name: string;
  lines: CapituloLinea[];
  subtotal: number;
}
const config = {
  visionWeight: 0.6,
  usuarioWeight: 0.4,
  alturaPlanta: 3.0,
  alturaAlero: 0.6,
  k: {
    andamio_ml: 35,
    sate_m2: 62,
    desmontaje_elemento: 45,
    canaleta_ml: 18,
    vierteaguas_ml: 22,
    panel_sandwich_m2: 68,
    teja_m2: 45,
    gestion_residuos_m3: 28,
    seguridad_salud: 0.03
  }
};
const item = items[0];
const data = item.json;
const state = data.state;
const vision: VisionEstimacion = data.vision || {};
const catastro = data.catastro || {};
const answers = state.answers;
const elementos: Elementos = answers.elements || {
  ac_units: 0,
  antennas: 0,
  pipes: 0,
  cables: 0,
  gutters: 0,
  solar_panels: 0
};
const fusion = (visionValue?: number, userValue?: number) => {
  if (visionValue && userValue) {
    return Number((visionValue * config.visionWeight + userValue * config.usuarioWeight).toFixed(2));
  }
  return Number((visionValue || userValue || 0).toFixed(2));
};
const perimeter = catastro.perimeter_ref || answers.perimeter_roof_m || 0;
const heights = catastro.heights_ref || answers.heights || 1;
const fachadaVisible = fusion(vision.facade_area_est, answers.facade_area_m2);
const huecos = vision.openings_area_est || 0;
const facadeNet = Number(Math.max(fachadaVisible - huecos, 0).toFixed(2));
const totalElementos: Elementos = {
  ac_units: Math.max(elementos.ac_units, vision.ac_units || 0),
  antennas: elementos.antennas,
  pipes: Math.max(elementos.pipes, vision.pipes || 0),
  cables: Math.max(elementos.cables, vision.cables || 0),
  gutters: Math.max(elementos.gutters, vision.gutters || 0),
  solar_panels: Math.max(elementos.solar_panels, vision.solar_panels || 0)
};
const alturaLineal = heights * config.alturaPlanta + config.alturaAlero;
const andamioML = perimeter;
const andamioM2 = Number((andamioML * alturaLineal).toFixed(2));
const sateM2 = facadeNet;
const cubiertaM2 = Number((perimeter * config.alturaPlanta).toFixed(2));
const residuosM3 = Number((sateM2 * 0.02 + cubiertaM2 * 0.01).toFixed(2));
const lineas: Capitulo[] = [];
function crearCapitulo(code: string, name: string): Capitulo {
  const cap: Capitulo = { code, name, lines: [], subtotal: 0 };
  lineas.push(cap);
  return cap;
}
function agregarLinea(cap: Capitulo, linea: CapituloLinea) {
  linea.importe = Number((linea.cantidad * linea.precio).toFixed(2));
  cap.lines.push(linea);
  cap.subtotal = Number((cap.subtotal + linea.importe).toFixed(2));
}
const cap01 = crearCapitulo('01', 'MEDIOS AUXILIARES');
agregarLinea(cap01, { codigo: '01.01', concepto: 'Andamio modular UNE 12810/11 montado y desmontado', unidad: 'm²', cantidad: andamioM2, precio: config.k.andamio_ml });
agregarLinea(cap01, { codigo: '01.02', concepto: 'Descuelgue vertical con línea de vida', unidad: 'ml', cantidad: perimeter, precio: 14 });
agregarLinea(cap01, { codigo: '01.03', concepto: 'Dirección facultativa y coordinación de seguridad', unidad: 'ud', cantidad: 1, precio: 850 });
const cap02 = crearCapitulo('02', 'REHABILITACIÓN DE FACHADA – SATE');
agregarLinea(cap02, { codigo: '02.01', concepto: 'Sistema SATE EPS 100 mm acabado acrílico', unidad: 'm²', cantidad: sateM2, precio: config.k.sate_m2 });
agregarLinea(cap02, { codigo: '02.02', concepto: 'Protecciones y recogidas previas', unidad: 'm²', cantidad: sateM2, precio: 4.5 });
agregarLinea(cap02, { codigo: '02.03', concepto: 'Desmontaje y montaje unidades climatización', unidad: 'ud', cantidad: totalElementos.ac_units, precio: config.k.desmontaje_elemento });
agregarLinea(cap02, { codigo: '02.04', concepto: 'Desmontaje y montaje antenas/toldos/canaletas', unidad: 'ud', cantidad: totalElementos.antennas + totalElementos.gutters, precio: 32 });
agregarLinea(cap02, { codigo: '02.05', concepto: 'Canaleta PVC/electricidad', unidad: 'ml', cantidad: totalElementos.cables, precio: config.k.canaleta_ml });
agregarLinea(cap02, { codigo: '02.06', concepto: 'Revestimiento vierteaguas aluminio lacado', unidad: 'ml', cantidad: perimeter, precio: config.k.vierteaguas_ml });
agregarLinea(cap02, { codigo: '02.07', concepto: 'Sellado y esmaltado de carpinterías y encuentros', unidad: 'ml', cantidad: perimeter * heights, precio: 9 });
const cap03 = crearCapitulo('03', 'REHABILITACIÓN DE CUBIERTA');
agregarLinea(cap03, { codigo: '03.01', concepto: 'Desmontaje de teja cerámica', unidad: 'm²', cantidad: cubiertaM2, precio: config.k.teja_m2 });
agregarLinea(cap03, { codigo: '03.02', concepto: 'Suministro e instalación panel sándwich 60 mm', unidad: 'm²', cantidad: cubiertaM2, precio: config.k.panel_sandwich_m2 });
agregarLinea(cap03, { codigo: '03.03', concepto: 'Ejecución limas, albardillas y remates', unidad: 'ml', cantidad: perimeter, precio: 38 });
agregarLinea(cap03, { codigo: '03.04', concepto: 'Revisión y sellado de claraboyas/solar', unidad: 'ud', cantidad: Math.max(totalElementos.solar_panels, 1), precio: 55 });
agregarLinea(cap03, { codigo: '03.05', concepto: 'Pruebas de servicio y estanqueidad', unidad: 'ud', cantidad: 1, precio: 220 });
const cap04 = crearCapitulo('04', 'INTERVENCIÓN SOBRE PLANTA BAJA');
agregarLinea(cap04, { codigo: '04.01', concepto: 'Aislamiento de vuelos/paso peatonal', unidad: 'm²', cantidad: Math.min(80, sateM2 * 0.1), precio: 54 });
agregarLinea(cap04, { codigo: '04.02', concepto: 'Saneado y pintura intumescente', unidad: 'm²', cantidad: Math.min(120, sateM2 * 0.12), precio: 18 });
agregarLinea(cap04, { codigo: '04.03', concepto: 'Acondicionamiento de accesos y señalización', unidad: 'ud', cantidad: 1, precio: 180 });
const cap05 = crearCapitulo('05', 'GESTIÓN DE RESIDUOS');
agregarLinea(cap05, { codigo: '05.01', concepto: 'Retirada y transporte a gestor autorizado', unidad: 'm³', cantidad: residuosM3, precio: config.k.gestion_residuos_m3 });
agregarLinea(cap05, { codigo: '05.02', concepto: 'Tasas y canon de vertedero', unidad: 'm³', cantidad: residuosM3, precio: 9 });
const cap06 = crearCapitulo('06', 'SEGURIDAD Y SALUD');
agregarLinea(cap06, { codigo: '06.01', concepto: 'Plan de seguridad y salud', unidad: 'ud', cantidad: 1, precio: 450 });
agregarLinea(cap06, { codigo: '06.02', concepto: 'Medios colectivos de protección', unidad: 'm²', cantidad: andamioM2, precio: 6 });
let total = lineas.reduce((acc, cap) => acc + cap.subtotal, 0);
const seguridad = Number((total * config.k.seguridad_salud).toFixed(2));
agregarLinea(cap06, { codigo: '06.03', concepto: 'Coste adicional seguridad y salud (3%)', unidad: 'ud', cantidad: 1, precio: seguridad });
cap06.subtotal = Number(cap06.lines.reduce((s, l) => s + l.importe, 0).toFixed(2));
total = Number(lineas.reduce((acc, cap) => acc + cap.subtotal, 0).toFixed(2));
return [{ json: { ...data, calc: { facade_area_net: facadeNet, chapters: lineas, total, config } } }];

// Prepara mensaje resumen y enlaces para WhatsApp.
const item = items[0];
const data = item.json;
const pdfUrl = data.body?.url || data.pdfUrl || data.responseData?.url || 'https://example.com/presupuesto.pdf';
const htmlUrl = data.headers?.location || data.responseHeaders?.Location || 'https://example.com/presupuesto.html';
const mensaje = `Aquí tienes el resumen de tu presupuesto. Total ejecución material: ${data.calc.total.toLocaleString('es-ES', { maximumFractionDigits: 2 })} €.
Descarga detalle PDF: ${pdfUrl}
Detalle HTML: ${htmlUrl}
¿Quieres que lo cree en Odoo y te lo enviemos por email/WhatsApp?`;
return [{ json: { ...data, reply: mensaje, action: 'solicitar_confirmacion' } }];

// Lógica de autenticación y creación de presupuesto en Odoo 17 vía JSON-RPC oficial.
const item = items[0];
const data = item.json;
const cred = {
  url: $env.ODOO_URL as string,
  db: $env.ODOO_DB as string,
  login: $env.ODOO_LOGIN as string,
  password: $env.ODOO_PASSWORD_OR_APIKEY as string
};
const orderPayload = {
  partner_id: data.state.answers.partner_id || data.incoming.contact_id || 1,
  client_order_ref: `WA-${data.phone}-${Date.now()}`,
  note: 'Generado automáticamente desde flujo n8n eficiencia energética',
  x_vision_ref: data.vision || {},
  validity_date: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString().substring(0, 10)
};
const headers = { 'Content-Type': 'application/json' };
const request = async (payload: any) => {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cred.url}/jsonrpc`,
    headers,
    body: payload,
    json: true,
    timeout: 10000
  });
  if (response.error) {
    throw new Error(response.error.data?.message || response.error.message || 'Error desconocido en Odoo');
  }
  return response.result;
};
async function crearPresupuesto() {
  const uid = await request({
    jsonrpc: '2.0',
    method: 'call',
    params: { service: 'common', method: 'login', args: [cred.db, cred.login, cred.password] },
    id: Date.now()
  });
  if (!uid) throw new Error('No se pudo autenticar en Odoo');
  const orderId = await request({
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [cred.db, uid, cred.password, 'sale.order', 'create', [orderPayload]]
    },
    id: Date.now() + 1
  });
  const lineas = data.calc.chapters.flatMap((cap: any) => {
    const sectionLine = {
      display_type: 'line_section',
      name: `${cap.code} ${cap.name}`,
      order_id: orderId
    };
    const partidas = cap.lines.map((linea: any) => ({
      name: `${linea.codigo} ${linea.concepto}`,
      product_uom_qty: linea.cantidad,
      price_unit: linea.precio,
      product_uom: 1,
      order_id: orderId
    }));
    return [sectionLine, ...partidas];
  });
  for (const linea of lineas) {
    await request({
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [cred.db, uid, cred.password, 'sale.order.line', 'create', [linea]]
      },
      id: Date.now() + Math.floor(Math.random() * 1000)
    });
  }
  return orderId;
}
return crearPresupuesto()
  .then(orderId => [{ json: { ...data, odooOrderId: orderId, reply: `Presupuesto creado en Odoo con ID ${orderId}. Te enviaremos copia por email.`, action: 'fin' } }])
  .catch(error => [{ json: { ...data, reply: `Odoo devolvió un error: ${error.message}. ¿Probamos de nuevo más tarde?`, action: 'error' } }]);
